Source excerpt, lines 35–54. def optimal_purchase_plan(remaining, count=30, sets=DEFAULT_SETS):
    sets = tuple(tuple(group) for group in sets)
    start = tuple(max(0, int(value)) for value in remaining)
    states = {start: (0, (), (0, 0, 0, 0))}
    milestones = []
    for _ in range(count):
        next_states = {}
        for resources, (cost, order, bought) in states.items():
            for index, group in enumerate(sets):
                missing = tuple(max(0, group[i] - resources[i]) for i in range(4))
                next_resources = tuple(resources[i] + missing[i] - group[i] for i in range(4))
                next_bought = tuple(bought[i] + missing[i] for i in range(4))
                candidate = (cost + sum(missing), order + (index + 1,), next_bought)
                current = next_states.get(next_resources)
                if current is None or (candidate[0], candidate[2], candidate[1]) < (current[0], current[2], current[1]):
                    next_states[next_resources] = candidate
        states = next_states
        best = min(states.values(), key=lambda value: (value[0], value[2], value[1]))
        milestones.append({'cost': best[0], 'order': list(best[1]), 'bought': list(best[2])})
    return milestones
